//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text-children.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}

#[test]
fn noscript_text_children_actual_append_insert_replace_remove_records_and_ranges(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),original=host.firstChild,a=document.createTextNode('A\udfff'),b=document.createTextNode('\ud800B'),c=document.createTextNode('<script>literal</script>'),watch=new MutationObserver(function(){}),range=document.createRange();range.setStart(host,1);range.setEnd(host,1);watch.observe(host,{childList:true,subtree:true});if(host.appendChild(a)!==a)throw 'append return';var rs=watch.takeRecords();if(host.lastChild!==a||a.previousSibling!==original||a.ownerDocument!==document||rs.length!==1||rs[0].target!==host||rs[0].addedNodes[0]!==a||rs[0].previousSibling!==original||rs[0].nextSibling!==null||range.startOffset!==1)throw 'actual append';if(host.insertBefore(b,a)!==b)throw 'insert return';rs=watch.takeRecords();if(b.nextSibling!==a||b.previousSibling!==original||rs.length!==1||rs[0].addedNodes[0]!==b||rs[0].previousSibling!==original||rs[0].nextSibling!==a)throw 'actual insert';host.insertBefore(b,b);if(watch.takeRecords().length||host.childNodes.length!==3)throw 'reference equal';if(host.replaceChild(c,b)!==b)throw 'replace return';rs=watch.takeRecords();if(b.parentNode!==null||b.data!=='\ud800B'||c.parentNode!==host||c.nextSibling!==a||rs.length!==1||rs[0].addedNodes[0]!==c||rs[0].removedNodes[0]!==b||rs[0].previousSibling!==original||rs[0].nextSibling!==a)throw 'actual replace';range.setStart(c,2);range.setEnd(c,4);if(host.removeChild(c)!==c)throw 'remove return';rs=watch.takeRecords();if(c.parentNode!==null||c.data!=='<script>literal</script>'||rs.length!==1||rs[0].removedNodes[0]!==c||rs[0].previousSibling!==original||rs[0].nextSibling!==a||range.startContainer!==host||range.endContainer!==host||range.startOffset!==1||range.endOffset!==1)throw 'actual remove and range';host.insertBefore(a,original);rs=watch.takeRecords();if(host.firstChild!==a||a.nextSibling!==original||rs.length!==2||rs[0].removedNodes[0]!==a||rs[1].addedNodes[0]!==a||rs[1].nextSibling!==original)throw 'actual same-parent move';if(host.innerHTML!=='A\udfffheld'||document.querySelectorAll('script').length||window.literal!==undefined)throw 'passive literal Text';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_children_move_between_hosts_and_ordinary_parent_with_actual_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var first=document.getElementById('host'),text=first.firstChild,second=first.cloneNode(false),out=document.getElementById('out'),watch=new MutationObserver(function(){}),range=document.createRange();document.body.appendChild(second);watch.observe(first,{childList:true});watch.observe(second,{childList:true});watch.observe(out,{childList:true});range.setStart(text,1);range.setEnd(text,3);second.appendChild(text);var rs=watch.takeRecords();if(first.firstChild!==null||second.firstChild!==text||text.parentNode!==second||rs.length!==2||rs[0].target!==first||rs[0].removedNodes[0]!==text||rs[1].target!==second||rs[1].addedNodes[0]!==text||range.startContainer!==first||range.endContainer!==first||range.startOffset||range.endOffset)throw 'passive source/destination move';out.appendChild(text);rs=watch.takeRecords();if(second.firstChild!==null||out.lastChild!==text||text.data!=='held'||text.ownerDocument!==document||rs.length!==2||rs[0].target!==second||rs[0].removedNodes[0]!==text||rs[1].target!==out||rs[1].addedNodes[0]!==text)throw 'passive to ordinary move';first.appendChild(text);rs=watch.takeRecords();if(first.firstChild!==text||out.textContent!=='Real'||rs.length!==2||rs[0].target!==out||rs[1].target!==first||rs[1].addedNodes[0]!==text)throw 'ordinary to passive move';"#);assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_text_children_nontext_native_ancestry_membership_guards_are_atomic(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),guarded=document.getElementById('guard'),text=host.firstChild,blocked=guarded.firstChild,span=document.createElement('span'),fresh=document.createTextNode('fresh'),watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 for (code,category) in [("host.appendChild(span);","inert resource subtrees"),("host.replaceChild(span,text);","inert resource subtrees"),("guarded.appendChild(fresh);","inert resource subtrees"),("host.appendChild(blocked);","inert resource subtrees"),("guarded.removeChild(blocked);","inert resource subtrees"),("host.removeChild(fresh);","NotFoundError"),("host.insertBefore(fresh,span);","NotFoundError")]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(e.contains(category),"{code}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||host.firstChild!==text||guarded.firstChild!==blocked||fresh.parentNode!==null||span.parentNode!==null)throw 'guard prefix';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_text_children_copy_work_retained_refusals_are_atomic_and_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var donor=document.implementation.createHTMLDocument('owner'),source=donor.createElement('noscript');for(var i=0;i<128;i++)source.appendChild(donor.createTextNode('x'));var host=document.importNode(source,true);document.body.appendChild(host);var text=host.firstChild,fresh=document.createTextNode('fresh'),watch=new MutationObserver(function(){}),range=document.createRange();range.setStart(text,0);range.setEnd(text,1);watch.observe(host,{childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let e=refusal(&mut d,&mut f,&mut p,"host.appendChild(fresh);").to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.childNodes.length!==128||host.firstChild!==text||fresh.parentNode!==null||watch.takeRecords().length||range.startContainer!==text||range.endContainer!==text||range.startOffset||range.endOffset!==1)throw 'quota atomic';");}p.begin_job();run(&mut d,&mut f,&mut p,"host.appendChild(fresh);var rs=watch.takeRecords();if(host.childNodes.length!==129||host.lastChild!==fresh||rs.length!==1||rs[0].addedNodes[0]!==fresh)throw 'fresh append recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
